procedure HardwareRefunds {
  about "Handle returned items and contact the customer"
  policy HardwarePolicy
  sheet Returns "Returns" { return_no: Text, customer: Text, phone: Phone, amount: Money, bought: Date, opened: Bool, status: Text }
  trigger when new row r in Returns

  if r.opened {
    notify owner "Opened return {r.return_no} for {r.customer}. Please handle it yourself."
    stop "opened return goes to owner"
  }
  if days_between(r.bought, today()) > 30 {
    notify owner "Old return {r.return_no} for {r.customer}. Please handle it yourself."
    stop "old return goes to owner"
  }
  if r.amount > $100.00 {
    notify owner "Large return {r.return_no} for {r.customer} is {r.amount}. Please handle it yourself."
    stop "large return goes to owner"
  }
  refund r.amount for r.return_no reason "returned item", ask owner first timeout 12 hours else stop "refund not approved"
  let m = draft sms to r.phone: "Hi {r.customer}, your return of {r.amount} has been refunded."
  let ok = request approval of m from owner timeout 12 hours else stop "message not approved"
  send ok
  update r set status = "refunded"
}
```

