procedure HardwareRefunds {
  about "On request, refund a return immediately"
  policy HardwarePolicy
  sheet Returns "Returns" { return_no: Text, customer: Text, phone: Phone, amount: Money, bought: Date, opened: Bool, status: Text }
  trigger when requested(return_no: Text)

  let this_return = find Returns where return_no == return_no else stop "return not found"
  refund this_return.amount for this_return.return_no reason "refund request", ask owner first timeout 12 hours else stop "refund not approved"
  update this_return set status = "refunded"
}

