procedure EscapeSummary {
  about "Tell the owner about recent booking data"
  policy EscapePolicy
  sheet Bookings "Bookings" { group_name: Text, leader_phone: Phone, slot: DateTime, players: Number, status: Text, waiver_notes: Text private }
  trigger every sunday at 09:00

  let all = fetch Bookings
  let these = filter all where status == "done"
  let n = summarize count of these
  let total = summarize sum players of these
  if n == 0 {
    notify owner "No done bookings in the last 7 days."
    stop "no data"
  }
  notify owner "Average group size: {round(total / n)}. Total: {n}."
}

