procedure OptomCancelledFollowUp {
  about "Follow up with the person who just had a cancellation"
  policy OptomPolicy
  sheet Cancellations "Cancellations" { event_id: Text, slot_text: Text }
  sheet Waitlist "Waitlist" { patient: Text, phone: Phone, joined: Date, status: Text }
  calendar Exams "Exams"
  trigger when new row r in Cancellations

  let first = find Waitlist where joined == r.joined and status == "waiting" else stop "no waiting patient"
  let m = draft sms to first.phone: "Hi {first.patient}, a spot opened for you! Reply with the time."
  let ok = request approval of m from owner timeout 1 day else stop "not approved"
  send ok
  update first set status = "offered"
}

