procedure IceRefunds {
  about "Handle refund requests within limits"
  policy IcePolicy
  sheet PartyCancellations "PartyCancellations" { ref: Text, host: Text, phone: Phone, deposit: Money, party_on: Date }
  trigger when new row r in PartyCancellations

  if r.party_on < today() + 3 days {
    notify owner "Short-notice refund for {r.host} ({r.deposit}). Please review."
    stop "short notice refund goes to owner"
  }
  if r.deposit > $100.00 {
    notify owner "Large refund for {r.host} ({r.deposit}). Please review."
    stop "large refund goes to owner"
  }
  if r.deposit <= $40.00 {
    refund r.deposit for r.ref reason "refund request"
  } else {
    refund r.deposit for r.ref reason "refund request", ask owner first timeout 12 hours else stop "refund not approved"
  }
  let m = draft sms to r.phone: "Hi {r.host}, your refund of {r.deposit} has been issued."
  let ok = request approval of m from owner timeout 12 hours else stop "message not approved"
  send ok
}
```

