procedure RepairFollowUpAfterWait {
  about "Contact a new ticket, then follow up later"
  policy RepairPolicy
  sheet Tickets "Tickets" { ticket: Text, customer: Text, email: Email, opened: Date, device: Text, status: Text, password: Text private }
  trigger when new row r in Tickets

  let first = draft email to r.email subject "Welcome": "Hi {r.customer default 'there'}, your ticket number is {r.ticket}. Questions? Just reply."
  let ok1 = request approval of first from owner timeout 1 day else skip
  send ok1
  wait 3 days
  let all = fetch Tickets
  let now_r = find all where email == r.email else stop "row was removed"
  if now_r.status == "new" {
    notify owner "Ticket {now_r.ticket} is still new by then. Please update me."
  }
}

