procedure FloristLateBalance {
  about "Remind late customers; escalate very late ones"
  policy FloristPolicy
  sheet Deliveries "Deliveries" { customer: Text, email: Email, deliver_on: Date, status: Text, price: Money, card_message: Text private }
  trigger every day at 08:00

  let all = fetch Deliveries
  let late = filter all where price > $0.00 and days_between(deliver_on, today()) > 5
  for each r in late up to 20 {
    if days_between(r.deliver_on, today()) > 14 {
      notify owner "{r.customer} is very late ({r.price}). Please call."
    } else {
      let m = draft email to r.email subject "A friendly reminder": "Hello {r.customer}, our records show a price of {r.price}. Questions? Just reply."
      let ok = request approval of m from owner timeout 12 hours else skip
      send ok
    }
  }
}
```

