procedure PlumbingOutreachCampaign {
  about "On request, contact recent cancelled customers"
  policy PlumbingPolicy
  sheet Calls "Calls" { customer: Text, phone: Phone, visit_at: DateTime, status: Text, invoice: Money, alarm_code: Text private }
  sheet Outreach "Outreach" { day: Date, campaign: Text, targeted: Number }
  trigger when requested(days: Number)

  let all = fetch Calls
  let targets = filter all where status == "cancelled" and days_between(visit_at, today()) <= days
