  let msgs = draft each r in targets up to 50 sms to r.phone: "Hi {r.customer}, come back to the company! Use code RETURN20 on your next visit."
  let ok = request batch approval of msgs from owner timeout 12 hours else stop "batch not approved"
  send ok
}
