procedure PhotostudioLateBalance {
  about "Remind late clients; escalate very late ones"
  policy PhotostudioPolicy
  sheet Shoots "Shoots" { client: Text, email: Email, shoot_on: Date, status: Text, deposit: Money, venue_notes: Text private }
  trigger every monday at 11:00

  let all = fetch Shoots
  let late = filter all where deposit > $0.00 and days_between(shoot_on, today()) > 7
  for each r in late up to 20 {
    if days_between(r.shoot_on, today()) > 21 {
      notify owner "{r.client} is very late ({r.deposit}). Please call."
    } else {
      let m = draft email to r.email subject "A friendly reminder": "Hello {r.client}, our records show a deposit of {r.deposit}. Questions? Just reply."
      let ok = request approval of m from owner timeout 12 hours else skip
      send ok
    }
  }
}
```

